head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


rownum = 2;
/**
 * @method
 * @name file_browse
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.file_browse = function() {
    //alert(rownum);
    if (scwin.rownum > 6) {
        alert("기타파일 업로드는 5개까지만 가능합니다.");
        return;
    } else {
        scwin.fn_addRow();
    }
};



//Row 추가
/**
 * @method
 * @name fn_addRow
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_addRow = function() {
    var rowPlus = document.getElementById("tbl_file");
    var tr;
    var th;
    var td;
    var newRowNum = scwin.rownum + 1;
    if (scwin.rownum == 0) {
        rowPlus.deleteRow(0);
    }
    var $tblFile = $('#tbl_file');
    var $tr = $("<tr></tr>");
    var $td1 = $("<td><input type=\"checkbox\" name=\"chk\" /></td>").addClass('first txl');
    var $td2 = $("<td><input type=\"hidden\" name=\"attach_file_tp_cd\" value=\"8\"/><img src=\"/images/btn_b1.png\" alt=\"선택\" style=\"vertical-align: top;\" />&nbsp;&nbsp;<font size=\"3\">기타</font></td>");
    var $td3 = $("<td><input type=\"text\" name=\"attach_file_nm[" + scwin.rownum + "]\" readonly style=\"width: 200px; height:20px; vertical-align: 6px;\" class=\"file_input_textbox\" /><div class=\"file_input_div\"><img src=\"/images/btn_find.gif\" name=\"file_1\" class=\"file_input_img_btn\" alt=\"open\" /><input type=\"file\" name=\"attachFiles[" + scwin.rownum + "]\" style=\"width:91px; height:20px; \" onchange=\"fn_getFileNm(" + scwin.rownum + ");\" class=\"file_input_hidden\" /></div></td>");
    var $td4 = $("<td><input type=\"text\" name=\"file_coment\" style=\"width: 310px; height:20px;\" maxlength=\"200\" onpaste=\"return false;\" /></td>");
    $tr.append($td1);
    $tr.append($td2);
    $tr.append($td3);
    $tr.append($td4);
    $tblFile.append($tr);
    scwin.rownum++;
    scwin.reNames();
};


//파일명추출
/**
 * @method
 * @name fn_getFileNm
 * @description desc
 * @param {string} rn desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getFileNm = function(rn) {
    //alert(rn);
    var objFile = $("input[name='attachFiles[" + rn + "]']");
    var temp = $("input[name='attachFiles[" + rn + "]']").val(); //원본파일
    var temp2 = temp.substring(temp.lastIndexOf('\\') + 1); //파일명 확장자포함
    var temp3 = temp2.substring(temp2.lastIndexOf('.') + 1); //확장자
    var temp4 = temp2.substring(0, temp2.lastIndexOf('.')); //파일명만
    //alert(objFile+'=='+temp+'=='+temp2+'=='+temp3+'=='+temp4);

    //파일명 길이체크
    //alert(file[file.length-2].length);
    if (temp4.length > 100) {
        alert("파일명이 100자를 초과하는 파일은 첨부 할 수 없습니다.");
        $("input[name='attachFiles[" + rn + "]']").val('');
        $("input[name='attach_file_nm[" + rn + "]']").val('');
        $("input[name='attach_file_nm[" + rn + "]']").focus();
        objFile.replaceWith(objFile.clone(true));
        return;
    }

    //허용 확장자 1개
    var extList = ["pdf"];
    var isTrue = false;
    for (var i = 0; i < 1; i++) {
        if (extList[i] == temp3.toLowerCase()) {
            isTrue = true;
        }
    }
    if (!isTrue && temp != '') {
        alert("첨부 불가능한 파일입니다.");
        $("input[name='attachFiles[" + rn + "]']").val('');
        $("input[name='attach_file_nm[" + rn + "]']").val('');
        $("input[name='attach_file_nm[" + rn + "]']").focus();
        objFile.replaceWith(objFile.clone(true));
        return;
    } else {
        //파일명 설정
        $("input[name='attach_file_nm[" + rn + "]']").val(temp2);
    }
};




//Row 삭제
/**
 * @method
 * @name fn_delRow
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_delRow = function() {
    var rowPlus = document.getElementById("tbl_file");
    var chk_num = 0;
    var isCheckedMandatoryFile = false; //필수파일 체크 여부.

    if (scwin.rownum > 0) {
        $i = 0;
        $('input[name=chk]').each(function() {
            if ($(this).is(":checked")) {
                chk_num++;

                //필수파일 삭제못하도록 체크
                var temp = $("input[name=attach_file_tp_cd]:eq(" + $i + ")").val();
                if (temp == "5" || temp == "6" || temp == "7" || temp == "13" || temp == "14" || temp == "17" || temp == "18") {
                    isCheckedMandatoryFile = true;
                } else {
                    rowPlus.deleteRow($i);
                    scwin.rownum--;
                    $i = $i - 1;
                    if (scwin.rownum == 0) {
                        var tr;
                        var th;
                        var td;
                        var newRowNum = scwin.rownum + 1;
                        tr = rowPlus.insertRow();
                        tr.addClass("first");
                        td = tr.insertCell();
                        td.colSpan = "4";
                        td.addClass("first txc");
                        td.innerHTML = "첨부파일이 없습니다.";
                        td.appendChild(td);
                    }
                }
            }
            $i = $i + 1;
        });
        if (isCheckedMandatoryFile) {
            alert("필수파일은 삭제 할 수 없습니다.");
        }
        if (chk_num == 0) {
            alert("선택된 행이 없습니다.");
            return;
        }
        scwin.reNames();
    } else if (scwin.rownum < 1) {
        alert("삭제 할 행이 없습니다.");
    }
};




//파일명 추출후 업로드 가능 확장자인지 확인.
/**
 * @method
 * @name fn_getFileNm1
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getFileNm1 = function() {
    var temp = $("input[name='batScdaplExcelFiles[0]']").val();
    $("input[name='batScdaplExcelFilesNm[0]']").val(temp.substring(temp.lastIndexOf('\\') + 1));
    var file_name = temp.substring(temp.lastIndexOf('\\') + 1);
    var file = file_name.split(".");
    var extList = new Array("xls", "xlsx");
    var fileChk = 0;
    for (var i = 0; i < extList.length; i++) {
        if (file[file.length - 1].toLowerCase() == extList[i]) fileChk = fileChk + 1;
    }
    if (fileChk == 0) {
        alert("첨부 불가능한 파일입니다.");
        $("input[name='batScdaplExcelFiles[0]']").val("");
        $("input[name='batScdaplExcelFilesNm[0]']").val("");
    }
};





//라디오버튼 text타입으로 값전달
/**
 * @method
 * @name fn_setAttach_chk
 * @description desc
 * @param {string} div desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setAttach_chk = function(div, val) {
    var frm = document.SendForm;
    if (scwin.rownum <= 1) {
        frm.attach_file_tp_cd.setValue(val);
    } else {
        frm.attach_file_tp_cd[div].setValue(val);
    }
};
/**
 * @method
 * @name reNames
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.reNames = function() {
    $.each($("input:file"), function(i) {
        //alert('1_'+i);
        $(this).attr("name", "attachFiles[" + i + "]");
        $(this).attr("onchange", "fn_getFileNm(" + i + ");");
    });
    $.each($("#SendForm").find("input[name*=attach_file_nm]"), function(i) {
        //alert('2_'+i);
        $(this).attr("name", "attach_file_nm[" + i + "]");
    });
    $.each($("#tbl_file tr"), function(i) {
        //alert('3_'+i);
        $(this).find("input:radio").attr("name", "attach_chk" + i);
        $(this).find("input:radio").attr("onclick", "fn_setAttach_chk(" + i + ", this.value)");
    });
};
/**
 * @method
 * @name selectAll
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.selectAll = function() {
    var checked = $("#chk_all").attr("checked");
    $.each($("#SendForm").find("input[name='chk']"), function(i) {
        var subChecked = $(this).attr("checked");
        if (subChecked != checked) {
            $(this).click();
        }
    });
    $.each($("#fileUploadList").find("input[name='chk']"), function(i) {
        var subChecked = $(this).attr("checked");
        if (subChecked != checked) {
            $(this).click();
        }
    });
};
